import unittest

from impl import rle_encode


class TestRLEEncode(unittest.TestCase):

    def test_empty_string(self):
        result = rle_encode("")
        self.assertEqual(result, "")

    def test_single_character(self):
        result = rle_encode("A")
        self.assertEqual(result, "A1")

    def test_all_same_characters(self):
        result = rle_encode("AAAAA")
        self.assertEqual(result, "A5")

    def test_alternating_characters(self):
        result = rle_encode("ABABAB")
        self.assertEqual(result, "A1B1A1B1A1B1")

    def test_consecutive_duplicates(self):
        result = rle_encode("AAABBBCCCDDEE")
        self.assertEqual(result, "A3B3C3D2E2")

    def test_mixed_with_single_chars(self):
        result = rle_encode("AABBCCDDEE")
        self.assertEqual(result, "A2B2C2D2E2")

    def test_edge_case_long_sequence(self):
        result = rle_encode("A" * 100)
        self.assertEqual(result, "A100")

    def test_edge_case_with_null_input(self):
        result = rle_encode(None)
        self.assertEqual(result, "")

    def test_edge_case_with_empty_string(self):
        result = rle_encode("   ")
        self.assertEqual(result, "   3")

    def test_edge_case_with_single_space(self):
        result = rle_encode(" ")
        self.assertEqual(result, "1")

    def test_edge_case_with_two_same_chars(self):
        result = rle_encode("AA")
        self.assertEqual(result, "A2")

    def test_edge_case_with_three_same_chars(self):
        result = rle_encode("AAA")
        self.assertEqual(result, "A3")

    def test_edge_case_with_different_lengths(self):
        result = rle_encode("AABBC")
        self.assertEqual(result, "A2B2C1")

    def test_edge_case_with_no_duplicates(self):
        result = rle_encode("ABCDEF")
        self.assertEqual(result, "A1B1C1D1E1F1")

    def test_edge_case_with_long_string(self):
        result = rle_encode("A" * 50 + "B" * 50)
        self.assertEqual(result, "A50B50")

    def test_edge_case_with_alternating_long_sequences(self):
        result = rle_encode("A" * 10 + "B" * 10 + "A" * 10)
        self.assertEqual(result, "A10B10A10")


if __name__ == "__main__":
    unittest.main()
