import unittest

from impl import binary_to_int


class TestBinaryToInt(unittest.TestCase):

    def test_empty_string_raises_value_error(self):
        with self.assertRaises(ValueError) as context:
            binary_to_int("")
        self.assertEqual(str(context.exception), 'empty string')

    def test_single_zero_returns_zero(self):
        self.assertEqual(binary_to_int("0"), 0)

    def test_single_one_returns_one(self):
        self.assertEqual(binary_to_int("1"), 1)

    def test_two_zeros_returns_zero(self):
        self.assertEqual(binary_to_int("00"), 0)

    def test_two_ones_returns_two(self):
        self.assertEqual(binary_to_int("11"), 3)

    def test_mixed_binary_string_returns_correct_value(self):
        self.assertEqual(binary_to_int("101"), 5)

    def test_binary_with_leading_zeros_returns_correct_value(self):
        self.assertEqual(binary_to_int("0101"), 5)

    def test_invalid_character_raises_value_error(self):
        with self.assertRaises(ValueError) as context:
            binary_to_int("102")
        self.assertEqual(str(context.exception), 'not binary')

    def test_invalid_character_at_end_raises_value_error(self):
        with self.assertRaises(ValueError) as context:
            binary_to_int("10a")
        self.assertEqual(str(context.exception), 'not binary')

    def test_invalid_character_in_middle_raises_value_error(self):
        with self.assertRaises(ValueError) as context:
            binary_to_int("1012")
        self.assertEqual(str(context.exception), 'not binary')

    def test_long_binary_string_returns_correct_value(self):
        self.assertEqual(binary_to_int("11111111"), 255)

    def test_binary_string_with_only_ones_returns_power_of_two_minus_one(self):
        self.assertEqual(binary_to_int("111"), 7)

    def test_binary_string_with_zero_and_one_returns_correct_value(self):
        self.assertEqual(binary_to_int("1001"), 9)

    def test_binary_string_with_multiple_zeros_and_ones_returns_correct_value(self):
        self.assertEqual(binary_to_int("1010101"), 85)


if __name__ == '__main__':
    unittest.main()
